package com.example.customers.domain;

import java.text.Normalizer;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

/** The name and status criteria used by customer page and count queries. */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        name = name == null ? "" : name;
        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
    }

    /** Whether the customer satisfies every active criterion. */
    public boolean matches(Customer customer) {
        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
            return false;
        }

        List<String> terms = nameTerms();
        if (terms.isEmpty()) {
            return true;
        }

        String firstName = normalize(customer.firstName());
        String lastName = normalize(customer.lastName());
        return terms.stream().allMatch(term ->
                firstName.contains(term) || lastName.contains(term));
    }

    private List<String> nameTerms() {
        if (name.isBlank()) {
            return List.of();
        }
        return Arrays.stream(name.strip().split("(?U)\\s+"))
                .map(CustomerFilter::normalize)
                .filter(term -> !term.isEmpty())
                .toList();
    }

    private static String normalize(String value) {
        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD)
                .toLowerCase(Locale.ROOT);
        return DIACRITICS.matcher(decomposed).replaceAll("");
    }
}

